// Generated by Claude (Opus 5.5), 2026-10-15
// crash-drills.cpp
// Feed handler harness broken on purpose, for stack trace recovery practice.
//
//   crash-drills null       book lookup returns nullptr once the price leaves the band -> SIGSEGV
//   crash-drills uaf        session roll frees the book, a cached pointer still writes to it -> SIGSEGV
//   crash-drills deadlock   parser and telemetry threads take two mutexes in opposite order -> hang
//
// Add --no-handler to skip the in-process backtrace handler.
//
// Build (from src/feed-handler/claude):
//   g++-14 -std=c++23 -g -O0 -fno-omit-frame-pointer -rdynamic -Wall -Wextra -Wshadow
//       crash-drills.cpp -o ../../../build/crash-drills

#include "synthetic-parser.hpp"
#include "../tick.hpp"

#include <execinfo.h>
#include <signal.h>
#include <sys/prctl.h>
#include <unistd.h>

#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <mutex>
#include <string_view>
#include <thread>

namespace crash_handler{

    // Only async-signal-safe calls in here: write(), backtrace_symbols_fd(), raise().
    // backtrace() itself is safe only after its first call, which install() makes.
    void on_signal(int sig, siginfo_t* info, void*){

        char msg[96];
        const int len = std::snprintf(msg, sizeof msg, "\n*** signal %d (%s), fault address %p\n",
                                      sig, sigabbrev_np(sig), info->si_addr);
        ::write(STDERR_FILENO, msg, len);

        void* frames[64];
        const int depth = ::backtrace(frames, 64);
        ::backtrace_symbols_fd(frames, depth, STDERR_FILENO);

        // SA_RESETHAND put the default action back: re-raise so the process still dies
        // with the original signal, and still dumps core.
        ::raise(sig);
    }

    void install(){

        // The first backtrace() dlopens libgcc_s, which allocates. Do it here, not in the handler.
        void* warm_up[1];
        ::backtrace(warm_up, 1);

        // A stack overflow leaves no stack to run the handler on.
        static char alt_stack[64 * 1024];
        stack_t ss{};
        ss.ss_sp = alt_stack;
        ss.ss_size = sizeof alt_stack;
        ::sigaltstack(&ss, nullptr);

        struct sigaction sa{};
        sa.sa_sigaction = on_signal;
        sa.sa_flags = SA_SIGINFO | SA_ONSTACK | SA_RESETHAND;
        sigemptyset(&sa.sa_mask);

        // SIGQUIT (Ctrl-\ or kill -QUIT) dumps the receiving thread's stack from a hung process.
        for ( int sig : {SIGSEGV, SIGBUS, SIGFPE, SIGILL, SIGABRT, SIGQUIT} )
            ::sigaction(sig, &sa, nullptr);
    }
}

enum class Mode{ null, uaf, deadlock };

struct Level{
    std::int64_t price;
    std::int64_t qty;
};

// 256 KiB: above malloc's mmap threshold, so delete hands the pages back to the kernel
// and a stale write faults instead of silently landing in the heap.
struct Book{
    static constexpr std::size_t depth = 16384;
    std::array<Level, depth> levels{};
    std::uint64_t updates{0};
};

struct Stats{
    std::uint64_t ticks{0};
    std::uint64_t book_updates{0};
};

class BookKeeper{

    public:

    explicit BookKeeper(Mode mode) : _mode(mode), _book(new Book{}), _hot(_book) {}

    ~BookKeeper(){
        delete _book;
    }

    void on_tick(const Tick& tick){

        std::lock_guard book_lock(_book_mtx);

        if ( _ref_price == 0 )
            _ref_price = tick.price;

        Book* book = book_for(tick.price);
        apply(*book, tick);

        ++_ticks;

        if ( _ticks == session_roll_at )
            roll_session();

        if ( _ticks % publish_every == 0 )
            publish_stats();
    }

    // Telemetry thread.
    void sample(Stats& out){

        if ( _mode == Mode::deadlock ){
            std::lock_guard stats_lock(_stats_mtx);
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
            std::lock_guard book_lock(_book_mtx);
            out = _stats;
            out.book_updates = _book->updates;
        }
        else{
            std::lock_guard book_lock(_book_mtx);
            std::lock_guard stats_lock(_stats_mtx);
            out = _stats;
            out.book_updates = _book->updates;
        }
    }

    private:

    static constexpr std::uint64_t session_roll_at = 5'000;
    static constexpr std::uint64_t publish_every = 1'000;

    // Levels either side of the reference price. The null drill uses a narrow band.
    std::int64_t band() const{
        return _mode == Mode::null ? 40 : static_cast<std::int64_t>(Book::depth / 2);
    }

    Book* book_for(std::int64_t price){

        const std::int64_t offset = price - _ref_price;

        if ( offset < -band() || offset >= band() ){
            if ( _mode == Mode::null )
                return nullptr;
            _ref_price = price;   // recentre
        }
        return _hot;
    }

    void apply(Book& book, const Tick& tick){

        const std::int64_t offset = tick.price - _ref_price + static_cast<std::int64_t>(Book::depth / 2);
        Level& level = book.levels[static_cast<std::size_t>(offset) % Book::depth];
        level.price = tick.price;
        level.qty += tick.qty;
        ++book.updates;
    }

    void roll_session(){

        Book* fresh = new Book{};
        delete _book;
        _book = fresh;

        if ( _mode != Mode::uaf )
            _hot = _book;   // the uaf drill forgets to refresh the cached pointer
    }

    // Called with _book_mtx held.
    void publish_stats(){

        if ( _mode == Mode::deadlock )
            std::this_thread::sleep_for(std::chrono::milliseconds(1));

        std::lock_guard stats_lock(_stats_mtx);
        _stats.ticks = _ticks;
    }

    Mode _mode;

    std::mutex _book_mtx;
    std::mutex _stats_mtx;

    Book* _book;
    Book* _hot;   // cached hot-path pointer to the current book
    std::int64_t _ref_price{0};
    std::uint64_t _ticks{0};
    Stats _stats{};
};

int main(int argc, char** argv){

    if ( argc < 2 ){
        std::fprintf(stderr, "usage: %s null|uaf|deadlock [--no-handler]\n", argv[0]);
        return 2;
    }

    const std::string_view arg = argv[1];
    Mode mode;
    if ( arg == "null" ) mode = Mode::null;
    else if ( arg == "uaf" ) mode = Mode::uaf;
    else if ( arg == "deadlock" ) mode = Mode::deadlock;
    else{
        std::fprintf(stderr, "unknown mode: %s\n", argv[1]);
        return 2;
    }

    if ( !(argc > 2 && std::string_view(argv[2]) == "--no-handler") )
        crash_handler::install();

    // kernel.yama.ptrace_scope=1 only lets a parent trace its children.
    // Opt in to being traced by any process of the same user, so gdb -p / eu-stack -p work unprivileged.
    ::prctl(PR_SET_PTRACER, PR_SET_PTRACER_ANY);

    std::fprintf(stderr, "pid %d, mode %s\n", ::getpid(), argv[1]);

    BookKeeper keeper(mode);

    std::atomic<bool> stop{false};
    std::thread telemetry([&]{
        Stats stats;
        while ( !stop.load(std::memory_order_relaxed) ){
            keeper.sample(stats);
            std::this_thread::sleep_for(std::chrono::microseconds(200));
        }
    });

    SyntheticParser<BookKeeper&> parser(keeper, {.max_ticks = 1'000'000});
    parser.start();

    stop.store(true);
    telemetry.join();

    std::printf("%llu ticks, no failure\n", static_cast<unsigned long long>(parser.ticks()));
    return 0;
}
